"use strict";
const levels = [require("./lib/level0.js"), require("./lib/level1.js"), require("./lib/level2.js"), require("./lib/level3.js"), require("./lib/level4.js"), require("./lib/level5.js")];
// Read once, when the package loads.
const requested = Number(process.env.ENVKIT_LEVEL || 1);
const level = levels[Math.min(Math.max(requested, 1), levels.length) - 1];
exports.mark = (text) => level.open + text + level.close;
